event {
Subroutine;
createRemainingObjectivesHud;
}
actions {
Create HUD Text(All Players(All Teams), Null, Custom String("Objectives Remaining: {0}", Subtract(Count Of(Global.objectivePositionList), True)), Null, Top, True, Null, Global.tmp2, Null, Visible To, Default Visibility);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Text ID);
}

event {
Subroutine;
setDifficulty;
}
actions {
Set Global Variable(difficultySetting, Count Of(Filtered Array(All Players(Team 1), Has Spawned(Current Array Element))));
If(Compare(Global.challengeSetting, >=, 4));
Set Global Variable(botHealthList, Array Slice(Global.numbersList, 90, 22));
Set Global Variable(botBiteDamageList, Array Slice(Global.numbersList, 112, 22));
Set Global Variable(botBiteDurationList, Array Slice(Global.numbersList, 134, 22));
Set Global Variable(botThrottleSpeedList, Empty Array);
For Global Variable(tmp0, 0, 22, True);
Modify Global Variable(botThrottleSpeedList, Append To Array, 1);
End;
Set Global Variable(botDamageDealtList, Array Slice(Global.numbersList, 156, 22));
Else;
Skip If(Compare(Total Time Elapsed, <, 100), True);
Small Message(All Players(All Teams), Custom String(" Difficulty adjusted for player count, change affects new zombies. "));
Set Global Variable(botHealthList, Array Slice(Global.numbersList, 178, 22));
Set Global Variable(botBiteDurationList, Array Slice(Global.numbersList, 200, 22));
If(Compare(Global.difficultySetting, ==, 1));
Set Global Variable(botBiteDamageList, Array Slice(Global.numbersList, 222, 22));
Set Global Variable(botBiteDurationList, Array Slice(Global.numbersList, 244, 22));
Set Global Variable(botThrottleSpeedList, Array Slice(Global.numbersList, 266, 22));
Set Global Variable(botDamageDealtList, Array Slice(Global.numbersList, 288, 22));
Else If(Compare(Global.difficultySetting, ==, 2));
Set Global Variable At Index(botHealthList, 18, 750);
Set Global Variable(botBiteDamageList, Array Slice(Global.numbersList, 310, 22));
Set Global Variable(botBiteDurationList, Array Slice(Global.numbersList, 332, 22));
Set Global Variable(botThrottleSpeedList, Array Slice(Global.numbersList, 354, 22));
Set Global Variable(botDamageDealtList, Array Slice(Global.numbersList, 376, 22));
Else If(Compare(Global.difficultySetting, >=, 5));
Set Global Variable(botHealthList, Array Slice(Global.numbersList, 398, 22));
Set Global Variable(botBiteDamageList, Array Slice(Global.numbersList, 420, 22));
Set Global Variable(botThrottleSpeedList, Array Slice(Global.numbersList, 442, 22));
Set Global Variable(botDamageDealtList, Array Slice(Global.numbersList, 464, 22));
Else;
Set Global Variable At Index(botHealthList, 18, 1000);
Set Global Variable(botBiteDamageList, Array Slice(Global.numbersList, 486, 22));
Set Global Variable(botThrottleSpeedList, Array Slice(Global.numbersList, 508, 22));
Set Global Variable(botDamageDealtList, Array Slice(Global.numbersList, 530, 22));
End;
End;
}

event {
Subroutine;
setPrematchTimer;
}
actions {
Abort If(Not(Global.menuFinaleMotionSlot));
If(Global.isVoting);
If(Compare((Event Player).isPregameVoting, ==, True));
Set Match Time(Global.menuFinaleMotionSlot);
Else;
If(And(Compare(Match Time, >, 35), Is True For All(All Players(Team 1), And(Compare((Current Array Element).isPregameVoting, ==, False), Compare((Current Array Element).pregameState, >, Null)))));
Set Match Time(35);
Else If(And(Compare(Match Time, >, 50), Compare(Count Of(Filtered Array(All Players(Team 1), And(Compare((Current Array Element).isPregameVoting, ==, False), Compare((Current Array Element).pregameState, >, Null)))), ==, Count Of(Filtered Array(All Players(Team 1), (Current Array Element).isPlayerActive)))));
Set Match Time(50);
End;
End;
Else;
If(Compare((Event Player).pregameState, <, 2));
Set Match Time(Global.menuFinaleMotionSlot);
Else;
Call Subroutine(shortenPrematchTimer);
End;
End;
}

event {
Subroutine;
shortenPrematchTimer;
}
actions {
If(And(Compare(Match Time, >, 10), Is True For All(All Players(Team 1), Compare((Current Array Element).pregameState, ==, 2))));
Set Match Time(15);
Wait(False, Ignore Condition);
Set Match Time(10);
Else If(And(Compare(Match Time, >, 20), Compare(Count Of(Filtered Array(All Players(Team 1), Compare((Current Array Element).pregameState, ==, 2))), ==, Count Of(Filtered Array(All Players(Team 1), (Current Array Element).isPlayerActive)))));
Set Match Time(20);
End;
}

event {
Subroutine;
enableDisableAbilities;
}
actions {
If(Global.isPregameSetup);
Disable Hero HUD(Event Player);
Set Primary Fire Enabled(Event Player, False);
Set Secondary Fire Enabled(Event Player, False);
Set Ability 1 Enabled(Event Player, False);
Set Ability 2 Enabled(Event Player, False);
Set Ultimate Ability Enabled(Event Player, False);
Set Melee Enabled(Event Player, False);
Else;
Set Primary Fire Enabled(Event Player, True);
Set Secondary Fire Enabled(Event Player, True);
Set Ability 1 Enabled(Event Player, True);
Set Ability 2 Enabled(Event Player, True);
Set Ultimate Ability Enabled(Event Player, True);
Set Melee Enabled(Event Player, True);
Enable Hero HUD(Event Player);
End;
}

event {
Subroutine;
objectivesManagement;
}
actions {
If(Global.isGameplayActive);
Set Global Variable(objectivePlayerList, Empty Array);
Set Global Variable(objectiveProgressSlot, Null);
Set Global Variable(isSmolderEventActive, False);
Set Global Variable(objectiveCheckpointSlot, Null);
Set Global Variable(isBiomorphingGoalPending, False);
If(True);
Skip(Value In Array(Array(18, Null, 3, 4, 7, 10, 13, 17), Add(True, Index Of Array Value(Array(1, 2, 3, 4, 5, 6, 7), Global.phaseSlot10))));
Play Effect(All Players(All Teams), Ring Explosion, Color(Orange), Global.currentObjectivePosition, Multiply(Global.objectiveRad, 2));
Play Effect(All Players(All Teams), Ring Explosion Sound, Color(Orange), Global.currentObjectivePosition, 200);
Else;
Else;
Play Effect(All Players(All Teams), Ring Explosion, Color(Green), Global.currentObjectivePosition, Global.objectiveRad);
Play Effect(All Players(All Teams), Ring Explosion Sound, Color(Rose), Global.currentObjectivePosition, 200);
Else;
Play Effect(All Players(All Teams), Ring Explosion, Color(Violet), Global.currentObjectivePosition, Global.objectiveRad);
Play Effect(All Players(All Teams), Ring Explosion Sound, Color(Violet), Global.currentObjectivePosition, 200);
Else;
Play Effect(All Players(All Teams), Ring Explosion Sound, Color(Red), Global.objectiveMotionSlot, 200);
Play Effect(All Players(All Teams), Ring Explosion, Color(Red), Global.objectiveMotionSlot, Multiply(Global.objectiveRad, 2));
Else;
Play Effect(All Players(All Teams), Ring Explosion Sound, Color(Lime Green), Global.currentObjectivePosition, 200);
Play Effect(All Players(All Teams), Ring Explosion, Color(Lime Green), Global.currentObjectivePosition, Multiply(Global.objectiveRad, 2));
Play Effect(All Players(All Teams), Bad Explosion, Color(Lime Green), Global.currentObjectivePosition, 3);
Else;
Play Effect(All Players(All Teams), Ring Explosion Sound, Color(Lime Green), Global.currentObjectivePosition, 200);
End;
If(And(Compare(Global.phaseSlot10, >=, 1), Compare(Global.phaseSlot10, <=, 7)));
Big Message(All Players(All Teams), Value In Array(String Split(Custom String("Showdown Conquered!0Giant zombie eliminated!0Biomorphing completed!0The survivors have been rescued!0The kill zone has been c{0}", Custom String("leared!0The egg has been destroyed!0Firing sequence complete!")), First Of(Null)), Subtract(Global.phaseSlot10, True)));
End;
Wait(False, Ignore Condition);
Modify Global Variable(objectivePositionList, Remove From Array By Index, False);
Call Subroutine(refreshCurrentObjectivePosition);
Modify Global Variable(objectiveTypeList, Remove From Array By Index, False);
Call Subroutine(refreshCurrentObjectiveType);
Set Global Variable(bossStateList, Empty Array);
Set Global Variable(objectiveActorSlot, Null);
End;
Wait(0.25, Ignore Condition);
If(Compare(Count Of(Global.objectivePositionList), ==, 1));
Set Global Variable(objectivePlayerList, Empty Array);
Set Global Variable(objectiveDescription, Custom String("Proceed to the extraction point"));
Chase Global Variable At Rate(extractionZoneRad, False, Global.extractionSpeedUp, Destination and Rate);
Set Global Variable(objectiveRad, 10);
Big Message(All Players(All Teams), Custom String("Get to the extraction point!"));
Else;
If(And(Compare(Global.phaseSlot10, >=, 1), Compare(Global.phaseSlot10, <=, 7)));
Set Global Variable(objectiveDescription, Value In Array(String Split(Custom String("Keep zombies away in the Showdown!0Eliminate the boss0Convert biowaste into powerups!0Rescue survivors0Clear the kill zone0De{0}", Custom String("stroy the egg0Repair satellite control terminals")), First Of(Null)), Subtract(Global.phaseSlot10, True)));
End;
If(And(Compare(Global.phaseSlot10, >=, 1), Compare(Global.phaseSlot10, <=, 7)));
Big Message(All Players(All Teams), Value In Array(String Split(Custom String("Proceed to the Showdown!0Eliminate the giant zombie!0Find the indicated material and deposit it!0Locate survivors and bring t{0}", Custom String("hem to the extraction site!0Get to the kill zone and clear zombies!0Destroy the zombie egg!0Repair the satellite control term{0}", Custom String("inals!"))), First Of(Null)), Subtract(Global.phaseSlot10, True)));
End;
If(True);
Skip(Value In Array(Array(33, Null, 6, 7, 18, 22, 26, 28), Add(True, Index Of Array Value(Array(1, 2, 3, 4, 5, 6, 7), Global.phaseSlot10))));
Set Global Variable(objectiveProgressSlot, Null);
Chase Global Variable At Rate(objectiveRad, Max(5, Divide(Global.objectiveProgressSlot, 4)), True, Destination and Rate);
Set Global Variable(objectiveColor, Color(Orange));
Set Global Variable(objectiveCheckpointSlot, 25);
Set Global Variable(objectiveQueueSlot, Empty Array);
Else;
Else;
Set Global Variable(objectiveProgressSlot, Null);
Set Global Variable(objectivePositionsSlot, Empty Array);
Set Player Variable(All Players(All Teams), biomorphingResourceAmount, Null);
Set Global Variable(objectiveColor, Color(Sky Blue));
Set Global Variable(objectiveRad, 3.5);
Set Global Variable(phaseSlot4, Array(Color(Blue), Color(Turquoise), Color(Sky Blue), Color(Red)));
Set Global Variable(phaseSlot3, String Split(Custom String("Head0Arm0Leg"), First Of(Null)));
Set Global Variable(objectiveQueueSlot, Randomized Array(Array(Null, 1, 2, 3)));
Set Global Variable(isBiomorphingGoalPending, True);
Set Global Variable(objectiveCheckpointSlot, 25);
Else;
Set Global Variable(objectiveActorSlot, Null);
Set Global Variable(objectiveRad, 10);
Set Global Variable(objectiveMotionSlot, Global.objectiveRad);
Else;
Set Global Variable(objectiveRad, 20);
Set Global Variable(objectiveMotionSlot, Global.currentObjectivePosition);
Set Global Variable(objectiveProgressSlot, Null);
Else;
Set Global Variable(objectiveRad, Null);
Else;
Set Global Variable(objectiveRad, 3);
Set Global Variable(objectiveColor, Color(Blue));
Set Global Variable(objectivePositionsSlot, Empty Array);
Set Global Variable(objectiveProgressSlot, Array(Null, Null, Null));
Set Global Variable(phaseSlot2, 50);
End;
End;
Set Global Variable(objectiveValue, Global.phaseSlot10);
For Global Variable(phaseSlot0, 0, Count Of(Global.objectiveEntityIdList), True);
Set Global Variable(tmp0, Value In Array(Global.objectiveEntityIdList, Global.phaseSlot0));
Destroy Progress Bar HUD Text(Global.tmp0);
Destroy Progress Bar In-World Text(Global.tmp0);
Destroy Effect(Global.tmp0);
Destroy HUD Text(Global.tmp0);
Destroy Icon(Global.tmp0);
Destroy In-World Text(Global.tmp0);
Wait(False, Ignore Condition);
End;
Set Global Variable(objectiveEntityIdList, Empty Array);
If(Compare(Global.objectiveValue, ==, 1));
If(Compare(Count Of(Global.objectivePositionList), ==, 1));
Create In-World Text(Remove From Array(All Players(All Teams), Global.objectivePlayerList), Custom String("Distance: {0}m", Distance Between(Global.currentObjectivePosition, If-Then-Else(Compare(Subtract(Y Component Of(Global.currentObjectivePosition), Y Component Of(Eye Position(Local Player))), <, 2), Vector(X Component Of(Position Of(Local Player)), Y Component Of(Global.currentObjectivePosition), Z Component Of(Position Of(Local Player))), Position Of(Local Player)))), Global.currentObjectivePosition, True, Do Not Clip, Visible To and String, Color(Sky Blue), Visible Never);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Text ID);
Create Effect(Filtered Array(All Living Players(Team 1), Compare(Global.extractionZoneRad, <, 200)), Sphere, Color(Lime Green), Global.currentObjectivePosition, Global.extractionZoneRad, Visible To Position and Radius);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Created Entity);
For Global Variable(tmp0, 0, 3, True);
Create Effect(All Players(All Teams), Light Shaft, Color(Sky Blue), Add(Global.currentObjectivePosition, Multiply(Subtract(Multiply(24, Global.tmp0), 2), Up)), Global.objectiveRad, Visible To);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Created Entity);
End;
Create Icon(Remove From Array(All Players(All Teams), Global.objectivePlayerList), Add(Global.currentObjectivePosition, Up), Arrow: Down, Visible To, Color(Sky Blue), True);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Created Entity);
Create In-World Text(Remove From Array(All Players(All Teams), Global.objectivePlayerList), Custom String("GET TO THE EXTRACTION POINT"), Add(Global.currentObjectivePosition, Multiply(5, Up)), 3, Do Not Clip, Visible To Position and String, Color(Sky Blue), Default Visibility);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Text ID);
Else;
Create In-World Text(Remove From Array(All Players(All Teams), Global.objectivePlayerList), Custom String("Distance: {0}m", Distance Between(Local Player, Global.currentObjectivePosition)), Global.currentObjectivePosition, True, Do Not Clip, Visible To String and Color, Global.objectiveColor, Visible Never);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Text ID);
Create Effect(Filtered Array(Local Player, Compare(Y Component Of(Position Of(Local Player)), >, Add(Y Component Of(Global.currentObjectivePosition), 4))), Ring, Global.objectiveColor, Global.currentObjectivePosition, Global.objectiveRad, Visible To Position Radius and Color);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Created Entity);
Create Effect(All Players(All Teams), Ring, Global.objectiveColor, Vector(X Component Of(Global.currentObjectivePosition), Y Component Of(Position Of(Local Player)), Z Component Of(Global.currentObjectivePosition)), Global.objectiveRad, Visible To Position Radius and Color);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Created Entity);
Create Effect(Global.objectivePlayerList, Light Shaft, Global.objectiveColor, Add(Global.currentObjectivePosition, Multiply(-30, Up)), Global.objectiveRad, Visible To Position Radius and Color);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Created Entity);
Create Effect(Filtered Array(All Players(All Teams), Compare(Global.objectivePlayerList, !=, Empty Array)), Light Shaft, Global.objectiveColor, Add(Global.currentObjectivePosition, Multiply(-10, Up)), Divide(Global.objectiveRad, 20), Visible To Position Radius and Color);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Created Entity);
Create Icon(Remove From Array(All Players(All Teams), Global.objectivePlayerList), Add(Global.currentObjectivePosition, Up), Arrow: Down, Visible To and Color, Global.objectiveColor, True);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Created Entity);
Create In-World Text(Global.objectivePlayerList, Custom String("CAPTURE PERCENTAGE: {0}%", Round To Integer(Global.objectiveProgressSlot, Down)), Add(Global.currentObjectivePosition, Up), 2, Do Not Clip, Visible To String and Color, Global.objectiveColor, Default Visibility);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Text ID);
Create HUD Text(All Players(All Teams), Custom String("Capture Percentage: {0}%", Round To Integer(Global.objectiveProgressSlot, Down)), Custom String("Objectives remaining: {0}", Subtract(Count Of(Global.objectivePositionList), True)), Custom String("{0} {1}", If-Then-Else(Compare(Global.objectivePlayerList, !=, Empty Array), Custom String("Allies: {0}", Count Of(Global.objectivePlayerList)), Empty Array), If-Then-Else(Compare(Global.objectiveQueueSlot, !=, Empty Array), Custom String("Foes: {0}", Count Of(Global.objectiveQueueSlot)), Empty Array)), Top, True, Global.objectiveColor, Global.objectiveColor, Global.objectiveColor, Visible To String and Color, Default Visibility);
Modify Global Variable(objectiveEntityIdList, Append To Array, Last Text ID);
